// 勞工保險條例 §13–15: 20% of the ordinary-risk premium on the insured grade, less any disability subsidy.
const facts = get(ctx.subject.employment, 'employee_extension_data.facts', {});
const wage = Math.max(0, get(ctx.subtotals, 'ORDINARY_WAGES', 0));
const insured = Number(get(facts, 'statutory.LI.elections.insured_amount', wage));
const born = get(ctx.subject.employment, 'payroll.date_of_birth', null);
const age = born == null || born === '' ? 0 : age_on(born, ctx.run.salary_coverage.to);
const continued = get(facts, 'statutory.LI.elections.continued_after_65', false) === true;
const subsidy = Number(get(facts, 'statutory.LI.elections.disability_subsidy', 0)) / 100;
if (get(ctx.subject.employer, 'entity_extension_data.li_no_insurance_unit', false) === true) return 0;
if (age >= ctx.lookup.maximum_ordinary_coverage_age_years && !continued) return 0;
return round(insured * ctx.lookup.rate * ctx.lookup.employee_share * (1 - subsidy), 1, 'HALF_UP');

