employee_amount:
// 全民健康保險法 §18, §27, §29: 30% employee share, subsidised on the worker's own share, plus one full share for each of up to three dependants.
const facts = get(ctx.subject.employment, 'employee_extension_data.facts', {});
const wage = Math.max(0, get(ctx.subtotals, 'ORDINARY_WAGES', 0));
const insured = Number(get(facts, 'statutory.NHI.elections.insured_amount', wage));
const elsewhere = get(facts, 'statutory.NHI.elections.insured_elsewhere', false) === true;
const exit = get(ctx.subject.employment, 'effective_range.to', '');
const dependants = Math.min(ctx.lookup.maximum_employee_dependants, Number(get(facts, 'statutory.NHI.elections.enrolled_dependants', 0)));
const subsidy = Number(get(facts, 'statutory.NHI.elections.disability_subsidy', 0)) / 100;
const own = round(insured * ctx.lookup.rate * ctx.lookup.employee_share, 1, 'HALF_UP');
if (elsewhere) return 0;
if (exit !== '' && !(exit >= ctx.run.salary_coverage.to)) return 0;
return round(own * (1 - subsidy) + own * dependants, 1, 'HALF_UP');

