employee_amount:
// 全民健康保險法 §31(1)(1); 扣取及繳納補充保險費辦法 §4, §6: 2.11% on the part of this bonus that takes the year's bonuses past four times the insured amount, at most NT$10,000,000 a payment.
const facts = get(ctx.subject.employment, 'employee_extension_data.facts', {});
const bonus = Math.max(0, get(ctx.subtotals, 'ADDITIONAL_WAGES', 0) - get(ctx.subtotals, 'ORDINARY_WAGES', 0));
const insured = Number(get(facts, 'statutory.NHI.elections.insured_amount', get(ctx.subtotals, 'ORDINARY_WAGES', 0)));
const year = String(get(ctx.run, 'pay_date', ctx.run.salary_coverage.to)).substring(0, 4);
const earlier = get(ctx.history, 'payslips', []).filter((slip) => String(get(slip, 'period', '')).substring(0, 4) === year);
const paid = earlier.reduce((total, slip) => total + Number(get(slip, 'additional_wages', 0)), 0);
const excess = Math.max(0, paid + bonus - ctx.lookup.bonus_salary_multiple * insured);
return round(Math.min(excess, bonus, ctx.lookup.payment_ceiling) * ctx.lookup.rate, 1, 'HALF_UP');

// 全民健康保險法 §31(1)(2): 2.11% on a salary payment to a worker insured elsewhere, charged whole from the minimum wage; overtime within 勞基法 §32 is not salary income (所得稅法 §14(1)(3)).
// ponytail: every overtime line is treated as within 勞基法 §32; split the hours past the monthly cap when the run can see them.
const facts = get(ctx.subject.employment, 'employee_extension_data.facts', {});
const exempt = get(facts, 'statutory.NHI_PART_TIME.elections.exempt', false) === true;
const elsewhere = get(facts, 'statutory.NHI.elections.insured_elsewhere', false) === true;
const payment = get(ctx.subtotals, 'ORDINARY_WAGES', 0) - ctx.overtime;
if (!elsewhere) return 0;
if (exempt) return 0;
if (!(payment >= ctx.lookup.part_time_payment_threshold)) return 0;
return round(Math.min(payment, ctx.lookup.payment_ceiling) * ctx.lookup.rate, 1, 'HALF_UP');

// 勞工退休金條例 §14(3): the worker's voluntary contribution, up to 6% of the monthly contribution wage.
const facts = get(ctx.subject.employment, 'employee_extension_data.facts', {});
const wage = Math.max(0, get(ctx.subtotals, 'ORDINARY_WAGES', 0));
const insured = Number(get(facts, 'statutory.LABOR_PENSION.elections.insured_amount', wage));
const residency = get(ctx.subject.employment, 'terms.residency_status', 'CITIZEN');
const rate = Number(get(facts, 'statutory.LABOR_PENSION.elections.voluntary_rate', 0)) / 100;
if (get(facts, 'statutory.LABOR_PENSION.elections.pension_system', 'NEW') === 'LSA') return 0;
const amount = round(insured * rate, 1, 'HALF_UP');
if (residency === 'CITIZEN') return amount;
if (residency === 'PERMANENT_RESIDENT') return amount;
if (get(facts, 'foreign_spouse_of_national', false) === true) return amount;
if (ctx.lookup.foreign_professional_covered !== true) return 0;
return get(facts, 'foreign_professional', false) === true ? amount : 0;

