// 勞工職業災害保險及保護法 §16–17: the insured grade times the notified experience rate, or the industry rate plus the 0.07% commuting rate.
const facts = get(ctx.subject.employment, 'employee_extension_data.facts', {});
const entity = get(ctx.subject.employer, 'entity_extension_data', {});
const wage = Math.max(0, get(ctx.subtotals, 'ORDINARY_WAGES', 0));
const insured = Number(get(facts, 'statutory.OCC_INJURY.elections.insured_amount', wage));
const experience = get(entity, 'occ_experience_rate_percent', null);
const risk = get(entity, 'risk_class', null);
const industry = risk == null ? null : get(ctx.lookup.industry_rate_percent, String(risk), null);
const base = industry == null ? ctx.lookup.default_rate_percent : industry;
const rate = experience != null ? Number(experience) : base + ctx.lookup.commuting_rate_percent;
return round(insured * rate / 100, 1, 'HALF_UP');

employee_amount:
// 薪資所得扣繳辦法 §6–7: without a 免稅額申報表 the resident salary bears 5% of the whole month, withheld above NT$2,000; with one, annualise the month, deduct the exemptions and the standard and salary deductions, apply the 所得稅法 §5 ladder and withhold a twelfth. Overtime within 勞基法 §32 is not salary income (所得稅法 §14(1)(3); 財政部台財稅第16713號).
// ponytail: every overtime line is treated as within 勞基法 §32; split the hours past the monthly cap when the run can see them.
const facts = get(ctx.subject.employment, 'employee_extension_data.facts', {});
const payDate = String(get(ctx.run, 'pay_date', ctx.run.salary_coverage.to));
const review = get(facts, 'statutory.INCOME_TAX.elections.tax_residency_reviews.' + payDate.substring(0, 4), null);
const residentFrom = get(review, 'resident_from', null);
const resident = residentFrom !== null && residentFrom <= payDate;
const wage = Math.max(0, get(ctx.subtotals, 'ORDINARY_WAGES', 0) - ctx.overtime - Number(get(ctx.statutory, 'LABOR_PENSION.employee', 0)));
const exemptions = get(facts, 'statutory.INCOME_TAX.elections.exemptions', null);
if (exemptions == null) {
  const flat = round(wage * ctx.lookup.rate, 1, 'DOWN');
  return resident && flat > ctx.lookup.minimum_withholding ? flat : 0;
}
const stepped = wage <= ctx.lookup.monthly_salary_rounding_threshold
  ? round(wage, ctx.lookup.monthly_salary_rounding_step, 'UP') - ctx.lookup.monthly_salary_rounding_step
  : wage;
const annual = 12 * stepped;
const deduction = ctx.lookup.annual_exemption_per_person * (1 + Math.max(0, Number(exemptions)))
  + ctx.lookup.annual_standard_deduction
  + Math.min(ctx.lookup.annual_salary_deduction, annual);
const scale = wage <= ctx.lookup.monthly_salary_rounding_threshold ? 10 : 1;
const tax = round(ladder(Math.max(0, annual - deduction), ctx.lookup.bands) / 12, scale, 'DOWN');
return resident && tax > ctx.lookup.minimum_withholding ? tax : 0;

// 各類所得扣繳率標準 §3(1): 18% of the reviewed non-resident's whole salary, or 6% at or below 1.5 times the minimum wage; overtime within 勞基法 §32 is not salary income (所得稅法 §14(1)(3)).
// ponytail: every overtime line is treated as within 勞基法 §32; split the hours past the monthly cap when the run can see them.
const facts = get(ctx.subject.employment, 'employee_extension_data.facts', {});
const payDate = String(get(ctx.run, 'pay_date', ctx.run.salary_coverage.to));
const review = get(facts, 'statutory.INCOME_TAX.elections.tax_residency_reviews.' + payDate.substring(0, 4), null);
const wage = Math.max(0, get(ctx.subtotals, 'ADDITIONAL_WAGES', 0) - ctx.overtime);
const rate = wage <= ctx.lookup.lower_rate_salary_ceiling ? ctx.lookup.lower_rate : ctx.lookup.rate;
if (review === null) return 0;
if (get(review, 'basis', '') !== 'NON_RESIDENT') return 0;
if (get(review, 'resident_from', null) !== null) return 0;
if (!(wage > 0)) return 0;
return round(wage * rate, 1, 'HALF_UP');

employer_amount:
// 全民健康保險法 §34: the employer's 2.11% supplementary premium on the pay above the insured amount; overtime within 勞基法 §32 is not salary income (所得稅法 §14(1)(3)).
// ponytail: every overtime line is treated as within 勞基法 §32; split the hours past the monthly cap when the run can see them.
const facts = get(ctx.subject.employment, 'employee_extension_data.facts', {});
const wage = Math.max(0, get(ctx.subtotals, 'GROSS', 0) - ctx.overtime);
const insured = Number(get(facts, 'statutory.NHI.elections.insured_amount', wage));
return round(Math.max(0, wage - insured) * ctx.lookup.rate, 1, 'HALF_UP');

// 勞動基準法 §56(1): 2%–15% of the wages of the workers still on the old pension system, at the rate the entity declares.
const facts = get(ctx.subject.employment, 'employee_extension_data.facts', {});
const entity = get(ctx.subject.employer, 'entity_extension_data', {});
const wage = Math.max(0, get(ctx.subtotals, 'ORDINARY_WAGES', 0));
const pension = get(facts, 'statutory.LABOR_PENSION.elections.pension_system', 'NEW');
const residency = get(ctx.subject.employment, 'terms.residency_status', 'CITIZEN');
const rate = Number(get(entity, 'pension_reserve_rate', ctx.lookup.default_rate_percent)) / 100;
// 勞動部 114年10月14日勞動福3字第1140153402A號令: from 2026-04-01 a 就業服務法 §46(1)(8)–(10) worker under ten years at the unit may leave the wage total.
const excludable = get(entity, 'pension_reserve_excludes_short_service_migrants', false) === true && get(facts, 'migrant_worker', false) === true;
if (excludable && calendar_completed_months(ctx.subject.employment.effective_range.from, add_days(ctx.run.salary_coverage.to, 1)) < 120) return 0;
const amount = round(wage * rate, 1, 'HALF_UP');
if (pension === 'LSA') return amount;
if (residency === 'CITIZEN') return 0;
if (residency === 'PERMANENT_RESIDENT') return 0;
if (get(facts, 'foreign_professional', false) === true) return 0;
return get(facts, 'foreign_spouse_of_national', false) === true ? 0 : amount;

employee_amount:
// 薪資所得扣繳辦法 §7: 5% on a non-monthly bonus payment at or above the 起扣標準.
const facts = get(ctx.subject.employment, 'employee_extension_data.facts', {});
const payDate = String(get(ctx.run, 'pay_date', ctx.run.salary_coverage.to));
const review = get(facts, 'statutory.INCOME_TAX.elections.tax_residency_reviews.' + payDate.substring(0, 4), null);
const residentFrom = get(review, 'resident_from', null);
const resident = residentFrom !== null && residentFrom <= payDate;
const bonus = get(ctx.subtotals, 'ADDITIONAL_WAGES', 0) - get(ctx.subtotals, 'ORDINARY_WAGES', 0);
return resident && bonus >= ctx.lookup.bonus_withholding_threshold ? round(bonus * ctx.lookup.rate, 1, 'HALF_UP') : 0;

// 所得稅法 §14(1)(9) with 各類所得扣繳率標準 §2: 6% withheld on the exit pay above the per-service-year exemption; a tail under six months counts as half a year.
const pay = Math.max(0, get(ctx.subtotals, 'RETIREMENT', 0) - get(ctx.subtotals, 'ADDITIONAL_WAGES', 0));
const payDate = String(get(ctx.run, 'pay_date', ctx.run.salary_coverage.to));
const start = get(ctx.subject.employment, 'effective_range.from', ctx.run.salary_coverage.from);
const end = get(ctx.subject.employment, 'effective_range.to', payDate);
const months = calendar_completed_months(start, add_days(end, 1));
const tail = months % 12;
const tail_years =
  tail === 0 ? 0
  : tail < 6 ? 0.5
  : 1;
const years = Math.floor(months / 12) + tail_years;
const exempt = ctx.lookup.exemption_per_service_year * years;
const facts = get(ctx.subject.employment, 'employee_extension_data.facts', {});
const review = get(facts, 'statutory.INCOME_TAX.elections.tax_residency_reviews.' + payDate.substring(0, 4), null);
const residentFrom = get(review, 'resident_from', null);
const resident = residentFrom !== null && residentFrom <= payDate;
return resident && pay > exempt ? round((pay - exempt) * ctx.lookup.rate, 1, 'HALF_UP') : 0;

// 職工福利金條例 §2(1)(3): 0.5% of the wage, deducted from the worker, where the entity has a welfare committee.
const entity = get(ctx.subject.employer, 'entity_extension_data', {});
const wage = Math.max(0, get(ctx.subtotals, 'ORDINARY_WAGES', 0));
return get(entity, 'welfare_committee_established', false) === true ? round(wage * ctx.lookup.employee_rate, 1, 'HALF_UP') : 0;

// 所得稅法 §14(1)(9) with 各類所得扣繳率標準 §2: 18% withheld on the exit pay above the per-service-year exemption; a tail under six months counts as half a year.
const pay = Math.max(0, get(ctx.subtotals, 'RETIREMENT', 0) - get(ctx.subtotals, 'ADDITIONAL_WAGES', 0));
const payDate = String(get(ctx.run, 'pay_date', ctx.run.salary_coverage.to));
const start = get(ctx.subject.employment, 'effective_range.from', ctx.run.salary_coverage.from);
const end = get(ctx.subject.employment, 'effective_range.to', payDate);
const months = calendar_completed_months(start, add_days(end, 1));
const tail = months % 12;
const tail_years =
  tail === 0 ? 0
  : tail < 6 ? 0.5
  : 1;
const years = Math.floor(months / 12) + tail_years;
const exempt = ctx.lookup.exemption_per_service_year * years;
const facts = get(ctx.subject.employment, 'employee_extension_data.facts', {});
const review = get(facts, 'statutory.INCOME_TAX.elections.tax_residency_reviews.' + payDate.substring(0, 4), null);
const residentFrom = get(review, 'resident_from', null);
const resident = residentFrom !== null && residentFrom <= payDate;
return !resident && pay > exempt ? round((pay - exempt) * ctx.lookup.rate, 1, 'HALF_UP') : 0;
